import React, { useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeTrades, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function formatTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString();
  } catch {
    return ts;
  }
}

function formatLoopMinutes(value) {
  const n = Number(value || 0);
  if (!n) return '—';
  return `${n.toFixed(1)} min`;
}

function TrendChart({ logs }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = canvas.offsetWidth || 520;
    const height = 280;

    canvas.width = width * 2;
    canvas.height = height * 2;
    canvas.style.height = `${height}px`;

    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, width, height);

    const data = [...(logs || [])]
      .slice(0, 20)
      .reverse()
      .map((log, idx) => ({
        x: idx + 1,
        y: Number(log?.risk_score || 0),
      }));

    const padL = 46;
    const padR = 18;
    const padT = 20;
    const padB = 40;
    const chartW = width - padL - padR;
    const chartH = height - padT - padB;

    const bg = ctx.createLinearGradient(0, 0, 0, height);
    bg.addColorStop(0, 'rgba(122,255,212,0.08)');
    bg.addColorStop(1, 'rgba(122,255,212,0)');
    ctx.fillStyle = bg;
    ctx.fillRect(padL, padT, chartW, chartH);

    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let y = 0; y <= 100; y += 20) {
      const py = padT + chartH - (y / 100) * chartH;
      ctx.beginPath();
      ctx.moveTo(padL, py);
      ctx.lineTo(width - padR, py);
      ctx.stroke();

      ctx.fillStyle = '#789089';
      ctx.font = '11px Inter';
      ctx.fillText(String(y), 16, py + 4);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.beginPath();
    ctx.moveTo(padL, padT);
    ctx.lineTo(padL, padT + chartH);
    ctx.lineTo(width - padR, padT + chartH);
    ctx.stroke();

    ctx.fillStyle = '#d7e7e0';
    ctx.font = '12px Inter';
    ctx.fillText('Risk score', 10, 14);
    ctx.fillText('Latest suspicious events', width / 2 - 56, height - 10);

    if (!data.length) {
      ctx.fillStyle = '#70817b';
      ctx.fillText('No risk events yet', padL + 12, padT + chartH / 2);
      return;
    }

    const points = data.map((d, i) => ({
      x: padL + (i / Math.max(data.length - 1, 1)) * chartW,
      y: padT + chartH - (d.y / 100) * chartH,
      raw: d.y,
      label: d.x,
    }));

    const area = ctx.createLinearGradient(0, padT, 0, padT + chartH);
    area.addColorStop(0, 'rgba(98,223,255,0.22)');
    area.addColorStop(1, 'rgba(98,223,255,0.01)');

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.lineTo(points[points.length - 1].x, padT + chartH);
    ctx.lineTo(points[0].x, padT + chartH);
    ctx.closePath();
    ctx.fillStyle = area;
    ctx.fill();

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.strokeStyle = '#7fffd4';
    ctx.lineWidth = 3;
    ctx.shadowColor = 'rgba(127,255,212,0.24)';
    ctx.shadowBlur = 16;
    ctx.stroke();
    ctx.shadowBlur = 0;

    points.forEach((p, i) => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4.2, 0, Math.PI * 2);
      ctx.fillStyle =
        p.raw >= 70 ? '#ff7f8d' : p.raw >= 40 ? '#ffc15d' : '#7fffd4';
      ctx.fill();

      if (i % 2 === 0 || points.length <= 8) {
        ctx.fillStyle = '#748883';
        ctx.font = '10px Inter';
        ctx.fillText(String(p.label), p.x - 3, padT + chartH + 16);
      }
    });

    ctx.fillStyle = '#ff7f8d';
    ctx.fillRect(width - 164, 16, 12, 3);
    ctx.fillStyle = '#d8e6e0';
    ctx.font = '11px Inter';
    ctx.fillText('Risk trend 0–100', width - 146, 20);
  }, [logs]);

  return <canvas ref={canvasRef} style={{ width: '100%', display: 'block' }} />;
}

function StatCard({ label, value, sub, tone = 'aurora', pulse = false }) {
  const toneClass =
    tone === 'danger'
      ? 'metric-danger'
      : tone === 'warning'
      ? 'metric-warning'
      : tone === 'cyan'
      ? 'metric-cyan'
      : 'metric-aurora';

  return (
    <div className={`glass-strong card-hover aurora-strip ${pulse ? 'fraud-pulse' : ''}`} style={{ padding: 22 }}>
      <div className="stat-label">{label}</div>
      <div className={`stat-value ${toneClass}`}>{value}</div>
      <div className="stat-sub">{sub}</div>
    </div>
  );
}

function RingPreview({ cycle }) {
  const path = Array.isArray(cycle?.cycle) ? cycle.cycle : [];
  const culprits = Array.isArray(cycle?.culprits) ? cycle.culprits : [];
  const rootTrades = Array.isArray(cycle?.root_trade_ids) ? cycle.root_trade_ids : [];

  return (
    <div style={{ padding: '14px 18px', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
      <div className="row-between" style={{ alignItems: 'flex-start' }}>
        <div>
          <div style={{ color: '#baffdf', fontWeight: 800, fontSize: 13 }}>
            {path.length ? path.join(' → ') : 'Cycle detected'}
          </div>
          <div style={{ color: '#7f938d', fontSize: 12, marginTop: 6 }}>
            Stock {cycle?.symbol || `#${cycle?.stock_id || '—'}`} • Depth {cycle?.max_depth || '—'} • Confidence {cycle?.confidence || 0}
          </div>
          <div style={{ color: '#69807a', fontSize: 12, marginTop: 4 }}>
            Culprits: {culprits.length ? culprits.join(', ') : '—'}
          </div>
          <div style={{ color: '#69807a', fontSize: 12, marginTop: 4 }}>
            Root trades: {rootTrades.length ? rootTrades.join(', ') : '—'}
          </div>
        </div>

        <div style={{ display: 'grid', gap: 8, minWidth: 112 }}>
          <span className="badge badge-high">{cycle?.occurrences || 1} loops</span>
          <span className="badge badge-low">{formatLoopMinutes(cycle?.fastest_loop_minutes)}</span>
        </div>
      </div>
    </div>
  );
}

export default function DashboardPage() {
  const navigate = useNavigate();

  const [stats, setStats] = useState({});
  const [trades, setTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [cycles, setCycles] = useState([]);

  const loadAll = async () => {
    try {
      const [statsRes, tradesRes, riskRes, cycleRes] = await Promise.all([
        api.fetchStats(),
        api.fetchTrades(1, 50),
        api.fetchFraudLogs(),
        api.fetchFraudCycles(),
      ]);

      setStats(statsRes || {});
      setRiskLogs(riskRes || []);
      setTrades(normalizeTrades(tradesRes || [], riskRes || []));
      setCycles(cycleRes || []);
    } catch (err) {
      console.error('DashboardPage loadAll error:', err);
    }
  };

  useEffect(() => {
    loadAll();

    const intervalId = setInterval(loadAll, 2000);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });

    socket.on('fraud_alert', loadAll);
    socket.on('fraud_detected', loadAll);
    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);
    socket.on('trust_score_updated', loadAll);

    return () => {
      clearInterval(intervalId);
      socket.disconnect();
    };
  }, []);

  const computed = useMemo(() => {
    const totalTrades = Number(stats?.total_trades ?? trades.length ?? 0);
    const fraudRings = Number(stats?.fraud_rings_detected ?? cycles.length ?? 0);
    const highRisk = Number(stats?.high_risk_traders ?? 0);
    const monitored = Number(stats?.monitored_traders ?? stats?.total_traders ?? 0);
    const highConfidence = Number(
      stats?.high_confidence_rings ??
        cycles.filter((c) => Number(c?.confidence || 0) >= 70).length
    );
    const recentRiskEvents = Number(
      stats?.recent_risk_events ??
        riskLogs.filter((log) => {
          if (!log?.detected_at) return false;
          return Date.now() - new Date(log.detected_at).getTime() <= 15 * 60 * 1000;
        }).length
    );
    const avgTrust = Number(stats?.avg_trust_score ?? 0);

    return {
      totalTrades,
      fraudRings,
      highRisk,
      monitored,
      highConfidence,
      recentRiskEvents,
      avgTrust,
    };
  }, [stats, trades, cycles, riskLogs]);

  const topCycles = useMemo(
    () =>
      [...cycles]
        .sort((a, b) => {
          const confDiff = Number(b?.confidence || 0) - Number(a?.confidence || 0);
          if (confDiff !== 0) return confDiff;
          return Number(b?.occurrences || 0) - Number(a?.occurrences || 0);
        })
        .slice(0, 8),
    [cycles]
  );

  const latestTrades = useMemo(() => trades.slice(0, 16), [trades]);
  const latestLogs = useMemo(() => riskLogs.slice(0, 20), [riskLogs]);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container">
        <div
          className="row-between"
          style={{ alignItems: 'flex-start', marginBottom: 28 }}
        >
          <div>
            <h1 className="page-title">
              TraceNet <span className="neon-strong">Dashboard</span>
            </h1>

            <div
              style={{
                marginTop: 12,
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                color: '#8da39d',
                fontSize: 14,
              }}
            >
              <span className="live-dot blink" />
              Live fraud monitoring, recursive ring analytics, and trust-aware surveillance
            </div>
          </div>

          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            <button className="btn-outline" onClick={() => navigate('/fraud')}>
              Fraud Engine
            </button>
            <button className="btn-outline" onClick={() => navigate('/traders')}>
              Traders
            </button>
          </div>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard
            label="Total Trades"
            value={computed.totalTrades}
            sub="All recorded market trade events"
            tone="aurora"
          />
          <StatCard
            label="Fraud Rings"
            value={computed.fraudRings}
            sub="Distinct grouped circular trading rings"
            tone="danger"
            pulse={computed.fraudRings > 0}
          />
          <StatCard
            label="High Confidence Rings"
            value={computed.highConfidence}
            sub="Confidence score at or above 70"
            tone="warning"
          />
          <StatCard
            label="Monitored Traders"
            value={computed.monitored}
            sub={`Average trust score ${computed.avgTrust.toFixed(1)}`}
            tone="cyan"
          />
        </div>

        <div className="grid-3" style={{ marginBottom: 20 }}>
          <div className="glass" style={{ padding: 18 }}>
            <div className="stat-label">High Risk Traders</div>
            <div className="stat-value metric-danger" style={{ fontSize: 30, marginBottom: 4 }}>
              {computed.highRisk}
            </div>
            <div className="stat-sub">Trust score below 40</div>
          </div>

          <div className="glass" style={{ padding: 18 }}>
            <div className="stat-label">Recent Risk Events</div>
            <div className="stat-value metric-warning" style={{ fontSize: 30, marginBottom: 4 }}>
              {computed.recentRiskEvents}
            </div>
            <div className="stat-sub">Detected in the last 15 minutes</div>
          </div>

          <div className="glass" style={{ padding: 18 }}>
            <div className="stat-label">Loop Engine</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
              <span className="live-dot-cyan blink" />
              <span style={{ color: '#d4e4de', fontWeight: 700 }}>Recursive SQL active</span>
            </div>
            <div className="stat-sub">
              Exact trading paths are reconstructed from the directed trade graph
            </div>
          </div>
        </div>

        <div className="grid-2" style={{ marginBottom: 20 }}>
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <div className="panel-header">
              <div>
                <div className="section-title">Recent Trades</div>
                <div className="section-subtitle">
                  Latest market transactions enriched with current fraud risk context
                </div>
              </div>

              <button className="btn-ghost" onClick={() => navigate('/fraud')}>
                View fraud
              </button>
            </div>

            <div className="scroll-y" style={{ maxHeight: 430 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Trade ID</th>
                    <th>Stock</th>
                    <th>Seller</th>
                    <th>Buyer</th>
                    <th>Price</th>
                    <th>Qty</th>
                    <th>Risk</th>
                  </tr>
                </thead>
                <tbody>
                  {latestTrades.map((trade) => (
                    <tr key={trade.trade_id}>
                      <td>#{trade.trade_id}</td>
                      <td>{trade.symbol || `#${trade.stock_id}`}</td>
                      <td>{trade.seller_name || `T${trade.seller_id}`}</td>
                      <td>{trade.buyer_name || `T${trade.buyer_id}`}</td>
                      <td>{Number(trade.price || 0).toFixed(2)}</td>
                      <td>{trade.quantity ?? '—'}</td>
                      <td>
                        <span className={badgeClass(trade.risk_score || 0)}>
                          {trade.risk_score || 0}
                        </span>
                      </td>
                    </tr>
                  ))}

                  {!latestTrades.length && (
                    <tr>
                      <td colSpan="7">
                        <div className="empty-state">No trades yet.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div style={{ display: 'grid', gap: 18 }}>
            <div className="glass-strong" style={{ padding: 20 }}>
              <div className="section-title" style={{ marginBottom: 6 }}>
                Risk Trend
              </div>
              <div className="section-subtitle" style={{ marginBottom: 12 }}>
                Y-axis is risk score 0–100, X-axis is the latest suspicious event sequence
              </div>
              <TrendChart logs={latestLogs} />
            </div>

            <div className="glass-strong" style={{ overflow: 'hidden' }}>
              <div className="panel-header">
                <div>
                  <div className="section-title">Detected Rings</div>
                  <div className="section-subtitle">
                    Explainable circular trading groups reconstructed from recursive traversal
                  </div>
                </div>
                <span className="badge badge-high">{cycles.length}</span>
              </div>

              <div className="scroll-y" style={{ maxHeight: 260 }}>
                {topCycles.map((cycle, idx) => (
                  <RingPreview cycle={cycle} key={cycle.cycle_id || idx} />
                ))}

                {!topCycles.length && (
                  <div className="empty-state">
                    No circular trading rings detected yet.
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="glass-strong" style={{ overflow: 'hidden' }}>
          <div className="panel-header">
            <div>
              <div className="section-title">Latest Risk Events</div>
              <div className="section-subtitle">
                Suspicious transactions scored using loop detection, trust score, repeated patterns, and abnormal movement
              </div>
            </div>

            <button className="btn-ghost" onClick={() => navigate('/fraud')}>
              Open engine
            </button>
          </div>

          <div className="scroll-y" style={{ maxHeight: 360 }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Trade</th>
                  <th>Score</th>
                  <th>Label</th>
                  <th>Reason</th>
                  <th>Detected</th>
                </tr>
              </thead>
              <tbody>
                {latestLogs.slice(0, 16).map((log, idx) => (
                  <tr key={`${log.risk_id || log.trade_id}-${idx}`}>
                    <td>#{log.trade_id}</td>
                    <td>{log.risk_score}</td>
                    <td>
                      <span className={badgeClass(log.risk_score)}>
                        {Number(log.risk_score || 0) >= 70
                          ? 'HIGH'
                          : Number(log.risk_score || 0) >= 40
                          ? 'MEDIUM'
                          : 'LOW'}
                      </span>
                    </td>
                    <td style={{ maxWidth: 560 }}>{log.reason}</td>
                    <td>{formatTime(log.detected_at)}</td>
                  </tr>
                ))}

                {!latestLogs.length && (
                  <tr>
                    <td colSpan="5">
                      <div className="empty-state">No risk events yet.</div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
